insert into iso27001_controls (system_name, control_id, title, theme, status, check_ids, evidence, last_checked)
values
  ('orcanos-qms', 'A.5.1', 'Policies for information security', 'Organizational', 'partial', '["org.policy_coverage"]'::jsonb, 'org.policy_coverage (partial): A company-wide information security policy exists but does not explicitly name/cover Orcanos QMS as a specific system (user attestation, 2026-09-15).', '2026-09-15'),
  ('orcanos-qms', 'A.5.2', 'Information security roles and responsibilities', 'Organizational', 'pass', '["org.roles_responsibilities"]'::jsonb, 'org.roles_responsibilities (pass): A named owner/responsible person for this system''s security exists (user attestation, 2026-09-15).', '2026-09-15'),
  ('orcanos-qms', 'A.5.3', 'Segregation of duties', 'Organizational', 'partial', '["code.static_authz_review", "org.roles_responsibilities"]'::jsonb, 'code.static_authz_review (partial): Account/tenant scoping enforced by per-endpoint convention (_require_account_member etc.), not a structural guarantee — no DB-level RLS backstop. A new module (fda_510k.py, found during this audit) had an unescaped id-filter IDOR gap; fixed during this audit run. | org.roles_responsibilities (pass): A named owner/responsible person for this system''s security exists (user attestation, 2026-09-15).', '2026-09-15'),
  ('orcanos-qms', 'A.5.4', 'Management responsibilities', 'Organizational', 'partial', '["org.policy_coverage"]'::jsonb, 'org.policy_coverage (partial): A company-wide information security policy exists but does not explicitly name/cover Orcanos QMS as a specific system (user attestation, 2026-09-15).', '2026-09-15'),
  ('orcanos-qms', 'A.5.5', 'Contact with authorities', 'Organizational', 'partial', '["org.incident_response_plan"]'::jsonb, 'org.incident_response_plan (partial): A general incident response plan exists but does not explicitly name Orcanos QMS or its specific escalation path (user attestation, 2026-09-15).', '2026-09-15'),
  ('orcanos-qms', 'A.5.6', 'Contact with special interest groups', 'Organizational', 'partial', '["org.policy_coverage"]'::jsonb, 'org.policy_coverage (partial): A company-wide information security policy exists but does not explicitly name/cover Orcanos QMS as a specific system (user attestation, 2026-09-15).', '2026-09-15'),
  ('orcanos-qms', 'A.5.7', 'Threat intelligence', 'Organizational', 'fail', '["code.dependency_vuln_scan", "org.policy_coverage"]'::jsonb, 'code.dependency_vuln_scan (fail): npm audit found 3 high-severity advisories (ws package, fixes available). Backend requirements.txt has no lockfile and uses floating >= version bounds. | org.policy_coverage (partial): A company-wide information security policy exists but does not explicitly name/cover Orcanos QMS as a specific system (user attestation, 2026-09-15).', '2026-09-15'),
  ('orcanos-qms', 'A.5.8', 'Information security in project management', 'Organizational', 'fail', '["code.secure_sdlc_review"]'::jsonb, 'code.secure_sdlc_review (fail): No CI pipeline runs tests, build, or a security gate (dependency audit/SAST/secret-scan) before deploy. No GitHub Actions found; cloudbuild.yaml deploys with no test step. No branch protection evidence.', '2026-09-15'),
  ('orcanos-qms', 'A.5.9', 'Inventory of information and other associated assets', 'Organizational', 'fail', '["org.asset_inventory"]'::jsonb, 'org.asset_inventory (fail): Orcanos QMS is not yet entered in the org''s asset inventory / Statement of Applicability (user attestation, 2026-09-15).', '2026-09-15'),
  ('orcanos-qms', 'A.5.10', 'Acceptable use of information and other associated assets', 'Organizational', 'partial', '["org.policy_coverage"]'::jsonb, 'org.policy_coverage (partial): A company-wide information security policy exists but does not explicitly name/cover Orcanos QMS as a specific system (user attestation, 2026-09-15).', '2026-09-15'),
  ('orcanos-qms', 'A.5.11', 'Return of assets', 'Organizational', 'pass', '["org.access_review_cadence"]'::jsonb, 'org.access_review_cadence (pass): A periodic (e.g. quarterly) access review is scheduled for this system''s admin/privileged roles (user attestation, 2026-09-15).', '2026-09-15'),
  ('orcanos-qms', 'A.5.12', 'Classification of information', 'Organizational', 'fail', '["org.asset_inventory"]'::jsonb, 'org.asset_inventory (fail): Orcanos QMS is not yet entered in the org''s asset inventory / Statement of Applicability (user attestation, 2026-09-15).', '2026-09-15'),
  ('orcanos-qms', 'A.5.13', 'Labelling of information', 'Organizational', 'fail', '["org.asset_inventory"]'::jsonb, 'org.asset_inventory (fail): Orcanos QMS is not yet entered in the org''s asset inventory / Statement of Applicability (user attestation, 2026-09-15).', '2026-09-15'),
  ('orcanos-qms', 'A.5.14', 'Information transfer', 'Organizational', 'fail', '["code.crypto_review", "supabase.network_restrictions"]'::jsonb, 'supabase.network_restrictions (fail): The production Postgres database''s network restrictions allow 0.0.0.0/0 and ::/0 — no network-layer access control, relying solely on credential secrecy.', '2026-09-15'),
  ('orcanos-qms', 'A.5.15', 'Access control', 'Organizational', 'partial', '["code.static_authz_review", "supabase.rls_policies", "pentest.idor_review"]'::jsonb, 'code.static_authz_review (partial): Account/tenant scoping enforced by per-endpoint convention (_require_account_member etc.), not a structural guarantee — no DB-level RLS backstop. A new module (fda_510k.py, found during this audit) had an unescaped id-filter IDOR gap; fixed during this audit run. | supabase.rls_policies (partial): No table in the project has Row Level Security enabled. All access is correctly centralized through the backend''s service_role key (valid architecture), but the frontend also ships a live anon key for the same project with no RLS as a defense-in-depth backstop. | pentest.idor_review (pass): Previously fixed cross-tenant IDOR issues (C2-C7, H2-H3) verified still intact. A new unescaped-id-filter IDOR/injection gap was found in the (then-new) 510(k) submissions module during this audit and fixed in the same session (backend/fda_510k.py — dossier_id/submission_id now sanitized with urllib.parse.quote before use in PostgREST filter strings).', '2026-09-15'),
  ('orcanos-qms', 'A.5.16', 'Identity management', 'Organizational', 'partial', '["code.authentication_review", "supabase.auth_config"]'::jsonb, 'code.authentication_review (partial): Hardcoded JWT fallback secret (''dev-secret-change-in-prod'') still present in backend/sessions.py (mitigated only by a separate startup validator, not removed at source). No MFA for any role. No rate limiting/lockout on login or password-reset-adjacent endpoints. | supabase.auth_config (partial): Password minimum length is only 6 characters with no complexity rule or HaveIBeenPwned check; MFA (TOTP) is available but not enforced; no session inactivity timeout configured; CAPTCHA disabled on public signup/login.', '2026-09-15'),
  ('orcanos-qms', 'A.5.17', 'Authentication information', 'Organizational', 'partial', '["code.secret_scanning", "supabase.api_key_management"]'::jsonb, 'code.secret_scanning (partial): No live secret currently tracked in git, but a real Orcanos credential exposed historically via .env.test and design/compliance/COMPLIANCE_HANDOFF.md remains in git history and has not been rotated.', '2026-09-15'),
  ('orcanos-qms', 'A.5.18', 'Access rights', 'Organizational', 'partial', '["org.access_review_cadence", "code.static_authz_review"]'::jsonb, 'org.access_review_cadence (pass): A periodic (e.g. quarterly) access review is scheduled for this system''s admin/privileged roles (user attestation, 2026-09-15). | code.static_authz_review (partial): Account/tenant scoping enforced by per-endpoint convention (_require_account_member etc.), not a structural guarantee — no DB-level RLS backstop. A new module (fda_510k.py, found during this audit) had an unescaped id-filter IDOR gap; fixed during this audit run.', '2026-09-15'),
  ('orcanos-qms', 'A.5.19', 'Information security in supplier relationships', 'Organizational', 'partial', '["org.subprocessor_dpa"]'::jsonb, 'org.subprocessor_dpa (partial): Not formally verified. Orcanos (the underlying data platform) holds ISO 27001 certification, which typically includes standard DPA-equivalent terms; Supabase and GCP both offer standard DPAs accepted via their terms of service. No one has explicitly confirmed the signed documents for this system (user attestation, 2026-09-15).', '2026-09-15'),
  ('orcanos-qms', 'A.5.20', 'Addressing information security within supplier agreements', 'Organizational', 'partial', '["org.subprocessor_dpa"]'::jsonb, 'org.subprocessor_dpa (partial): Not formally verified. Orcanos (the underlying data platform) holds ISO 27001 certification, which typically includes standard DPA-equivalent terms; Supabase and GCP both offer standard DPAs accepted via their terms of service. No one has explicitly confirmed the signed documents for this system (user attestation, 2026-09-15).', '2026-09-15'),
