-- ─────────────────────────────────────────────────────────────────────────
-- 005_iso27001_controls.sql
--
-- Run ONCE against the MASTER / platform Supabase database — the same one
-- holding `accounts`, `users`, `security_audit_log`.
--
-- WHY IT EXISTS. The `compliance-audit` Claude skill (Orcanos QMS repo,
-- ~/.claude/skills/compliance-audit) runs a per-system ISO 27001:2022 Annex A
-- audit and writes its results to a JSON ledger file inside that system's own
-- repo (`Orcanos QMS/compliance/ledger.json`). That's fine for a diffable
-- source of truth, but it means the findings only exist as a file on one
-- machine — nobody can browse them, resolve one, or attach evidence without
-- opening a repo and editing JSON by hand.
--
-- This table is the durable, multi-system home for those findings: one row
-- per Annex A control per audited system (`system_name`), carrying the
-- automated status/evidence from the last skill run PLUS a manual resolution
-- (an operator's answer to "is it documented?", an optional evidence link,
-- who answered, when). The skill's JSON ledger stays the audit trail of *code
-- and infra scans*; this table is where a human closes out the parts a scan
-- can never answer on its own (policy coverage, DPAs, asset inventory, ...).
--
-- MULTI-SYSTEM ON PURPOSE. `system_name` is not a customer account — it is
-- which internal *product* was audited ('orcanos-qms' today; 'account-
-- management' itself, 'traceability-matrix', etc. as the skill is run against
-- them). One control_id (e.g. 'A.5.1') therefore has one row per system, not
-- one row overall — a policy gap in Orcanos QMS says nothing about whether
-- this app has the same gap.
--
-- SEED DATA is the actual 2026-09-15 Orcanos QMS run (93 Annex A controls),
-- carried over from `Orcanos QMS/compliance/ledger.json` so the very first
-- thing this screen shows is real, not empty. `on conflict do nothing` makes
-- re-running this file harmless — it will never overwrite a resolution an
-- operator has already entered.
-- ─────────────────────────────────────────────────────────────────────────

create table if not exists iso27001_controls (
  id                       uuid primary key default gen_random_uuid(),
  system_name              text not null,              -- which internal product was audited, e.g. 'orcanos-qms'
  control_id               text not null,               -- Annex A clause, e.g. 'A.5.1'
  title                    text not null,
  theme                    text not null,               -- Organizational | People | Physical | Technological
  status                   text not null,               -- pass | partial | fail | blocked | not_applicable
  check_ids                jsonb not null default '[]', -- which compliance-audit skill checks produced this status
  evidence                 text,                        -- automated finding text from the last skill run
  last_checked             date,                         -- when the automated scan last touched this control

  -- manual resolution — an operator closing out what a scan alone can't answer
  resolved                 boolean not null default false,
  resolution_answer        text,                        -- e.g. "Yes — see the security policy doc" / "Not yet"
  resolution_evidence_link text,
  resolved_status          text,                        -- the status the operator asserts (pass|partial|fail|not_applicable), independent of the automated `status`
  resolved_by              bigint,                       -- master users.id, no FK (same convention as agent_definitions.created_by)
  resolved_at              timestamptz,

  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now()
);

create unique index if not exists idx_iso27001_controls_system_control
  on iso27001_controls(system_name, control_id);

create index if not exists idx_iso27001_controls_system_status
  on iso27001_controls(system_name, status);

comment on table iso27001_controls is
  'ISO/IEC 27001:2022 Annex A control status per internal system, seeded from the '
  'compliance-audit Claude skill''s JSON ledger and resolved here by an operator. '
  'See sql/005_iso27001_controls.sql for the full design note.';


on conflict (system_name, control_id) do nothing;
